def is_swing_high(data, i, lookback=5):
    if i < lookback or i >= len(data) - lookback:
        return False
    high = data['high'][i]
    for j in range(i - lookback, i + lookback + 1):
        if j != i and data['high'][j] >= high:
            return False
    return True

def is_swing_low(data, i, lookback=5):
    if i < lookback or i >= len(data) - lookback:
        return False
    low = data['low'][i]
    for j in range(i - lookback, i + lookback + 1):
        if j != i and data['low'][j] <= low:
            return False
    return True

def adx_regime(adx, trend_threshold=25, range_threshold=20):
    """
    Classify regime based on ADX
    """
    if adx > trend_threshold:
        return 'trending'
    elif adx < range_threshold:
        return 'ranging'
    else:
        return 'transitional'

